# Capability substitution and failover: Search Provider Failover
primary = "primary-search-api"; substitutes = "secondary-search-api;cse-fallback".split(";")
FAIL = True
def call(cap):
    if cap == primary and FAIL:
        raise RuntimeError("primary down: 3 consecutive failures or p99 > 2s")
    return "result-from-" + cap
for cap in [primary] + substitutes:
    try:
        print(call(cap)); break
    except RuntimeError as e:
        print("failover:", e)
print("OK - substitution kept the work going")

